def get_Odd_Occurrence(arr, n):
    """
    Find the element that occurs an odd number of times in the array.
    """
    count = {}
    for num in arr:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
    for key, value in count.items():
        if value % 2 == 1:
            return key
    return None
