def sum_of_divisors(n):
    """Return the sum of all divisors of n (including 1 and n itself)."""
    if n <= 0:
        return 0
    total = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def areEquivalent(a, b):
    """Check whether the sum of divisors of a and b are the same."""
    return sum_of_divisors(a) == sum_of_divisors(b)
