def common_prefix(strings, max_len):
    if not strings:
        return ""

    # Find the minimum length among all strings, but cap it at max_len
    min_len = min(len(s) for s in strings)
    min_len = min(min_len, max_len)

    if min_len == 0:
        return ""

    # Check character by character
    for i in range(min_len):
        char = strings[0][i]
        for s in strings:
            if s[i] != char:
                return strings[0][:i]

    return strings[0][:min_len]
```

