def find_Min(arr, low, high):
    # Base case: only one element
    if low == high:
        return arr[low]

    # If the array is not rotated (already sorted)
    if arr[low] < arr[high]:
        return arr[low]

    mid = (low + high) // 2

    # Check if mid is the minimum
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid]

    # If mid element is greater than high, min is in right half
    if arr[mid] > arr[high]:
        return find_Min(arr, mid + 1, high)

    # Otherwise, min is in left half
    return find_Min(arr, low, mid - 1)
```

