def babylonian_squareroot(n):
    if n < 0:
        raise ValueError("Cannot compute square root of negative number")
    if n == 0:
        return 0.0

    # Initial guess
    guess = n / 2.0

    # Iterate until convergence
    while True:
        new_guess = (guess + n / guess) / 2.0
        if abs(new_guess - guess) < 1e-15:
            return new_guess
        guess = new_guess
