def max_length(list_of_lists):
    """
    Find the list with maximum length from a list of lists.

    Args:
        list_of_lists: A list of lists

    Returns:
        A tuple containing the maximum length and the list with that length
    """
    if not list_of_lists:
        return (0, [])

    max_len = 0
    max_list = []

    for lst in list_of_lists:
        if len(lst) > max_len:
            max_len = len(lst)
            max_list = lst

    return (max_len, max_list)
```

